import{_ as n,c as e,o as i,ae as t}from"./chunks/framework.BlRNOFgT.js";const p=JSON.parse('{"title":"Latihan Soal: SEO (Search Engine Optimization)","description":"","frontmatter":{},"headers":[],"relativePath":"WBD/seo.md","filePath":"WBD/seo.md"}'),s={name:"WBD/seo.md"};function l(r,a,o,u,d,m){return i(),e("div",null,[...a[0]||(a[0]=[t(`<h1 id="latihan-soal-seo-search-engine-optimization" tabindex="-1">Latihan Soal: SEO (Search Engine Optimization) <a class="header-anchor" href="#latihan-soal-seo-search-engine-optimization" aria-label="Permalink to &quot;Latihan Soal: SEO (Search Engine Optimization)&quot;">​</a></h1><h2 id="bagian-1-konsep-dasar-cara-kerja-search-engine" tabindex="-1">Bagian 1: Konsep Dasar &amp; Cara Kerja Search Engine <a class="header-anchor" href="#bagian-1-konsep-dasar-cara-kerja-search-engine" aria-label="Permalink to &quot;Bagian 1: Konsep Dasar &amp; Cara Kerja Search Engine&quot;">​</a></h2><p><strong>1. Dalam konteks pemrosesan aplikasi web modern (berbasis JavaScript), manakah pernyataan yang BENAR mengenai antrean (queues) pada Googlebot?</strong></p><ul><li>A. Semua halaman langsung dirender segera setelah crawling.</li><li>B. Terdapat pemisahan antara proses crawling awal dengan proses rendering.</li><li>C. Rendering JavaScript adalah proses yang intensif sumber daya dan bisa tertunda dari detik hingga minggu.</li><li>D. Googlebot selalu mengeksekusi JavaScript pada fase Indexing, bukan Rendering.</li><li>E. Chromium &quot;evergreen&quot; digunakan untuk merender halaman.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: B, C, E</strong></p><p><strong>Penjelasan:</strong> Googlebot memisahkan crawling dan rendering. Halaman masuk ke &quot;Rendering Queue&quot; (antrean) karena proses ini resource-intensive. Pengecoh (D) salah karena eksekusi JS terjadi di fase Rendering, sebelum Indexing.</p></details><hr><p><strong>2. Manakah dari elemen berikut yang termasuk dalam faktor penentu peringkat (Ranking Factors) teknis?</strong></p><ul><li>A. Kecepatan First Input Delay (FID) atau Interaction to Next Paint (INP).</li><li>B. Penggunaan protokol HTTPS.</li><li>C. Jumlah keyword yang diulang sebanyak mungkin dalam satu paragraf (Keyword Stuffing).</li><li>D. Penerapan Structured Data.</li><li>E. Kualitas backlink dari situs lain.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: A, B, D, E</strong></p><p><strong>Penjelasan:</strong> Opsi C (Keyword Stuffing) adalah praktik buruk yang harus dihindari. Sisa opsi lainnya adalah faktor valid yang mempengaruhi ranking (Page Experience, Security, Structured Data, Relevance/Authority).</p></details><hr><h2 id="bagian-2-crawling-indexing-technicalities" tabindex="-1">Bagian 2: Crawling &amp; Indexing Technicalities <a class="header-anchor" href="#bagian-2-crawling-indexing-technicalities" aria-label="Permalink to &quot;Bagian 2: Crawling &amp; Indexing Technicalities&quot;">​</a></h2><p><strong>3. Sebuah file <code>robots.txt</code> memiliki konfigurasi di bawah ini. Manakah implikasi teknis yang VALID dari konfigurasi tersebut?</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>User-agent: *</span></span>
<span class="line"><span>Disallow: /admin/</span></span>
<span class="line"><span>Disallow: /temp/</span></span>
<span class="line"><span>Allow: /admin/public/</span></span></code></pre></div><ul><li>A. Folder <code>/admin/</code> sepenuhnya tidak akan di-crawl oleh bot apapun.</li><li>B. Bot diizinkan mengakses <code>/admin/public/</code> meskipun direktori induknya <code>/admin/</code> di-disallow.</li><li>C. Konfigurasi ini secara otomatis mencegah halaman <code>/temp/</code> muncul di hasil pencarian meskipun ada link eksternal yang mengarah ke sana.</li><li>D. Bot tidak akan menelusuri folder <code>/temp/</code>.</li><li>E. File CSS dan JavaScript di dalam root folder otomatis terblokir.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: B, D</strong></p><p><strong>Penjelasan:</strong> Aturan Allow yang lebih spesifik dapat menimpa Disallow pada direktori induk (B benar). robots.txt hanya memblokir crawling, bukan indexing (jika ada backlink, halaman masih bisa terindeks, jadi C salah). E salah karena tidak ada aturan yang memblokir CSS/JS.</p></details><hr><p><strong>4. Mengenai XML Sitemap, manakah praktik terbaik (Best Practices) yang harus diterapkan pengembang?</strong></p><ul><li>A. Memasukkan semua URL, termasuk yang memiliki status 404 atau 301, agar Google tahu statusnya.</li><li>B. Memecah sitemap jika jumlah URL melebihi 50.000.</li><li>C. Hanya menyertakan URL kanonikal (canonical URLs).</li><li>D. Menggunakan atribut <code>&lt;priority&gt;</code> untuk memaksa Google meranking halaman lebih tinggi.</li><li>E. Menyerahkan (submit) sitemap melalui Search Console.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: B, C, E</strong></p><p><strong>Penjelasan:</strong> Sitemap harus bersih, hanya berisi URL kanonikal yang valid (200 OK). Opsi A salah karena URL error/redirect tidak boleh masuk. Opsi D salah karena <code>&lt;priority&gt;</code> hanya petunjuk prioritas crawling, bukan jaminan ranking.</p></details><hr><h2 id="bagian-3-url-struktur-halaman" tabindex="-1">Bagian 3: URL &amp; Struktur Halaman <a class="header-anchor" href="#bagian-3-url-struktur-halaman" aria-label="Permalink to &quot;Bagian 3: URL &amp; Struktur Halaman&quot;">​</a></h2><p><strong>5. Manakah dari struktur URL berikut yang dianggap &quot;SEO-Friendly&quot; dan mengikuti best practices?</strong></p><ul><li>A. <code>https://example.com/products/gaming_laptop_pro</code></li><li>B. <code>https://example.com/blog/technical-seo-guide</code></li><li>C. <code>https://example.com/index.php?category=laptop&amp;id=123</code></li><li>D. <code>https://example.com/electronics/smartphones</code></li><li>E. <code>https://example.com/ABOUT/Team-Members</code></li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: B, D</strong></p><p><strong>Penjelasan:</strong> A menggunakan underscore (_) yang kurang disukai dibanding hyphen (-). C menggunakan parameter dinamis. E menggunakan huruf kapital (sebaiknya lowercase untuk konsistensi). Hanya B dan D yang bersih, deskriptif, dan menggunakan hyphen.</p></details><hr><p><strong>6. Mengapa URL Rewriting penting dalam pengembangan aplikasi web?</strong></p><ul><li>A. Untuk mengubah URL dinamis yang penuh parameter menjadi URL statis yang mudah dibaca manusia.</li><li>B. Untuk menyembunyikan ekstensi file seperti <code>.php</code> atau <code>.html</code> demi keamanan saja.</li><li>C. Memungkinkan penyisipan keyword relevan langsung ke dalam path URL.</li><li>D. Memudahkan crawler memproses struktur situs.</li><li>E. Menggantikan fungsi robots.txt dalam memblokir halaman.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: A, C, D</strong></p><p><strong>Penjelasan:</strong> URL Rewriting fokus pada readability, keyword inclusion, dan crawlability. Opsi B bukan alasan utama SEO, dan E salah karena fungsinya berbeda total dengan robots.txt.</p></details><hr><p><strong>7. Terkait kode status HTTP, manakah pernyataan yang akurat mengenai dampaknya terhadap SEO?</strong></p><ul><li>A. Status 301 meneruskan sekitar 90-99% link equity ke URL baru.</li><li>B. Status 302 memberi sinyal kepada Google bahwa perubahan bersifat permanen.</li><li>C. Status 404 adalah penalti bagi website dan harus dihilangkan sepenuhnya.</li><li>D. &quot;Soft 404&quot; terjadi ketika server mengembalikan status 200 OK untuk halaman yang kontennya tidak ada/hilang.</li><li>E. Status 503 digunakan untuk downtime sementara agar Googlebot tahu situs akan kembali.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: A, D, E</strong></p><p><strong>Penjelasan:</strong> B salah karena 302 adalah temporary. C salah karena 404 natural tidak memberi penalti, yang bermasalah adalah broken link internal. D dan A adalah definisi teknis yang tepat.</p></details><hr><h2 id="bagian-4-metadata-masalah-duplikasi" tabindex="-1">Bagian 4: Metadata &amp; Masalah Duplikasi <a class="header-anchor" href="#bagian-4-metadata-masalah-duplikasi" aria-label="Permalink to &quot;Bagian 4: Metadata &amp; Masalah Duplikasi&quot;">​</a></h2><p><strong>8. Anda sedang mengonfigurasi tag <code>&lt;head&gt;</code> untuk SEO. Manakah implementasi yang BENAR?</strong></p><ul><li>A. <code>&lt;title&gt;</code> harus unik untuk setiap halaman dan idealnya 50-60 karakter.</li><li>B. <code>&lt;meta name=&quot;keywords&quot;&gt;</code> adalah tag paling penting untuk ranking Google saat ini.</li><li>C. <code>&lt;link rel=&quot;canonical&quot; href=&quot;...&quot;&gt;</code> digunakan untuk mengatasi masalah konten duplikat pada URL dengan parameter.</li><li>D. <code>&lt;meta name=&quot;viewport&quot;&gt;</code> penting untuk SEO mobile-friendliness.</li><li>E. <code>&lt;meta name=&quot;description&quot;&gt;</code> harus diisi dengan teks yang sama di semua halaman untuk konsistensi branding.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: A, C, D</strong></p><p><strong>Penjelasan:</strong> B salah karena Google mengabaikan meta keywords. E salah karena meta description harus unik untuk setiap halaman agar relevan di hasil pencarian.</p></details><hr><p><strong>9. Kasus Duplikasi Konten: Sebuah halaman produk dapat diakses melalui http, https, www, dan non-www. Solusi teknis apa yang paling tepat untuk menyatukan sinyal SEO?</strong></p><ul><li>A. Menggunakan robots.txt untuk memblokir versi http.</li><li>B. Mengimplementasikan tag <code>&lt;link rel=&quot;canonical&quot;&gt;</code> yang mengarah ke versi preferensi (misal: <code>https://www...</code>).</li><li>C. Membiarkan Google memilih sendiri versi terbaik.</li><li>D. Melakukan redirect 301 dari semua varian ke satu versi utama.</li><li>E. Menambahkan parameter <code>?ref=canonical</code> di setiap URL.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: B, D</strong></p><p><strong>Penjelasan:</strong> Solusi standar adalah Canonical Tag (B) atau 301 Redirects (D). Memblokir via robots.txt (A) berbahaya karena menghapus akses. Membiarkan Google (C) berisiko dilusi ranking.</p></details><hr><h2 id="bagian-5-javascript-seo-spa" tabindex="-1">Bagian 5: JavaScript SEO &amp; SPA <a class="header-anchor" href="#bagian-5-javascript-seo-spa" aria-label="Permalink to &quot;Bagian 5: JavaScript SEO &amp; SPA&quot;">​</a></h2><p><strong>10. Apa tantangan utama Single Page Applications (SPA) murni (Client-Side Rendering) di mata crawler tradisional?</strong></p><ul><li>A. Crawler mungkin hanya melihat &quot;cangkang&quot; HTML kosong (empty HTML shell) sebelum JavaScript dieksekusi.</li><li>B. SPA tidak memiliki URL sama sekali.</li><li>C. Navigasi menggunakan Hash Fragments (<code>/#/page</code>) tidak dapat di-crawl dengan andal oleh Googlebot.</li><li>D. Meta tags di SPA tidak bisa dibaca walaupun sudah diubah lewat DOM.</li><li>E. Potensi terjadinya Soft 404 karena routing ditangani di sisi klien.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: A, C, E</strong></p><p><strong>Penjelasan:</strong> B salah karena SPA punya URL. D salah karena Googlebot modern bisa membaca perubahan DOM jika dirender, tapi tantangannya ada di waktu rendering, bukan ketidakmampuan total. A, C, E adalah tantangan valid SPA.</p></details><hr><p><strong>11. Untuk memperbaiki navigasi SPA agar ramah SEO, pengembang harus beralih dari Hash Fragments ke History API. Manakah potongan kode atau konsep yang relevan dengan solusi ini?</strong></p><ul><li>A. Menggunakan <code>&lt;a href=&quot;#/products&quot;&gt;</code></li><li>B. Menggunakan fungsi <code>window.history.pushState({}, &#39;&#39;, url)</code></li><li>C. Server harus dikonfigurasi untuk menangani rute URL langsung (bukan hanya root).</li><li>D. Menggunakan <code>&lt;a href=&quot;/products&quot;&gt;</code> (path absolut/relatif standar).</li><li>E. Mengandalkan onClick event listener tanpa tag <code>&lt;a&gt;</code> yang valid.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: B, C, D</strong></p><p><strong>Penjelasan:</strong> A adalah cara lama (Hash) yang buruk. E buruk untuk aksesibilitas dan SEO. B, C, D adalah komponen implementasi History API yang benar.</p></details><hr><p><strong>12. Bagaimana cara menangani Soft 404 pada aplikasi SPA (Client-Side Rendering) ketika produk tidak ditemukan di API?</strong></p><ul><li>A. Membiarkan halaman tetap tampil kosong dengan status 200 OK.</li><li>B. Melakukan redirect via JavaScript (<code>window.location.href</code>) ke halaman 404 khusus.</li><li>C. Menyuntikkan meta tag <code>&lt;meta name=&quot;robots&quot; content=&quot;noindex&quot;&gt;</code> secara dinamis ke dalam DOM.</li><li>D. Mengubah status kode HTTP header menjadi 404 menggunakan JavaScript di sisi klien (browser).</li><li>E. Menampilkan pesan &quot;Not Found&quot; di layar tanpa mengubah apapun di balik layar.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: B, C</strong></p><p><strong>Penjelasan:</strong> D tidak mungkin dilakukan karena JS di browser tidak bisa mengubah response header yang sudah diterima dari server. A dan E adalah penyebab Soft 404. Solusi valid adalah redirect (B) atau menyuntikkan noindex (C).</p></details><hr><p><strong>13. Manakah keuntungan menggunakan Server-Side Rendering (SSR) dibandingkan Client-Side Rendering (CSR) untuk SEO?</strong></p><ul><li>A. Googlebot dapat melihat konten HTML lengkap segera saat request pertama.</li><li>B. Menghilangkan kebutuhan akan file sitemap.xml.</li><li>C. Mempercepat Initial Page Load yang berdampak positif pada Core Web Vitals.</li><li>D. Memudahkan berbagi tautan di media sosial (preview tautan muncul benar).</li><li>E. Menghapus ketergantungan pada JavaScript sepenuhnya.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: A, C, D</strong></p><p><strong>Penjelasan:</strong> B salah, sitemap tetap butuh. E salah, JS tetap dipakai untuk interaktivitas (hydration). A, C, D adalah keunggulan utama SSR.</p></details><hr><h2 id="bagian-6-optimasi-lanjutan-core-web-vitals" tabindex="-1">Bagian 6: Optimasi Lanjutan &amp; Core Web Vitals <a class="header-anchor" href="#bagian-6-optimasi-lanjutan-core-web-vitals" aria-label="Permalink to &quot;Bagian 6: Optimasi Lanjutan &amp; Core Web Vitals&quot;">​</a></h2><p><strong>14. Terkait Dynamic Meta Tags dengan JavaScript, manakah kode yang BENAR untuk memperbarui deskripsi halaman secara dinamis?</strong></p><ul><li>A. <code>document.title = &#39;New Description&#39;;</code></li><li>B. Mencari elemen meta dengan <code>querySelector(&#39;meta[name=&quot;description&quot;]&#39;)</code> lalu mengubah atribut <code>.content</code>-nya.</li><li>C. Jika meta deskripsi belum ada, membuatnya dengan <code>document.createElement(&#39;meta&#39;)</code> lalu menambahkannya ke <code>document.head</code>.</li><li>D. Googlebot tidak akan pernah membaca perubahan meta tag yang dilakukan lewat JavaScript.</li><li>E. <code>document.body.appendChild(metaDesc);</code></li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: B, C</strong></p><p><strong>Penjelasan:</strong> A mengubah judul, bukan deskripsi. D salah (Googlebot bisa baca setelah rendering). E salah (meta tag harus di head, bukan body).</p></details><hr><p><strong>15. Mengenai Lazy Loading gambar untuk performa SEO, manakah praktik yang disarankan?</strong></p><ul><li>A. Menggunakan atribut native <code>&lt;img loading=&quot;lazy&quot;&gt;</code>.</li><li>B. Menerapkan Lazy Loading pada semua gambar, termasuk gambar utama di bagian paling atas (above-the-fold).</li><li>C. Menggunakan API <code>IntersectionObserver</code> untuk kompatibilitas atau kontrol lebih lanjut.</li><li>D. Tidak perlu menentukan dimensi width dan height jika sudah di-lazy load.</li><li>E. Memberikan dimensi placeholder untuk mencegah pergeseran tata letak (Layout Shift).</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: A, C, E</strong></p><p><strong>Penjelasan:</strong> B salah karena gambar above-the-fold (LCP element) harus dimuat segera, jangan di-lazy load. D salah karena tanpa dimensi akan merusak CLS (Cumulative Layout Shift).</p></details><hr><p><strong>16. Structured Data membantu mesin pencari memahami konten. Manakah fakta yang benar?</strong></p><ul><li>A. Format yang direkomendasikan Google adalah JSON-LD.</li><li>B. Structured Data ditempatkan di dalam tag <code>&lt;script type=&quot;application/ld+json&quot;&gt;</code>.</li><li>C. Implementasi ini menjamin halaman pasti muncul di peringkat 1.</li><li>D. Memungkinkan munculnya Rich Results (seperti bintang review, resep, event).</li><li>E. Syntax harus mengikuti kosakata dari schema.org.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: A, B, D, E</strong></p><p><strong>Penjelasan:</strong> C salah besar. SEO tidak pernah menjamin peringkat 1. Structured Data hanya membantu visibility dan tampilan (Rich Results), bukan jaminan ranking instan.</p></details><hr><p><strong>17. Core Web Vitals mengukur pengalaman pengguna. Pasangan metrik dan target yang benar adalah:</strong></p><ul><li>A. LCP (Largest Contentful Paint) harus kurang dari 2.5 detik.</li><li>B. FID (First Input Delay) mengukur stabilitas visual.</li><li>C. CLS (Cumulative Layout Shift) targetnya harus di bawah 0.1.</li><li>D. INP (Interaction to Next Paint) adalah pengganti FID untuk mengukur responsivitas/interaktivitas.</li><li>E. LCP mengukur seberapa cepat server merespon (Time to First Byte).</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: A, C, D</strong></p><p><strong>Penjelasan:</strong> B salah (FID mengukur interaktivitas, bukan stabilitas). E salah (LCP mengukur elemen terbesar terlihat, bukan respon server awal). A, C, D benar sesuai standar.</p></details><hr><h2 id="bagian-7-mobile-audit" tabindex="-1">Bagian 7: Mobile &amp; Audit <a class="header-anchor" href="#bagian-7-mobile-audit" aria-label="Permalink to &quot;Bagian 7: Mobile &amp; Audit&quot;">​</a></h2><p><strong>18. Apa implikasi dari Mobile-First Indexing?</strong></p><ul><li>A. Google hanya mengindeks situs yang dibuka dari HP, situs desktop diabaikan.</li><li>B. Google menggunakan versi mobile dari konten untuk proses indexing dan ranking.</li><li>C. Konten pada versi mobile dan desktop harus setara (same content).</li><li>D. Structured data hanya perlu ada di versi desktop.</li><li>E. Kecepatan loading di perangkat seluler menjadi faktor krusial.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: B, C, E</strong></p><p><strong>Penjelasan:</strong> A salah (Desktop tetap diindeks tapi sekunder). D salah (harus ada di kedua versi). Intinya adalah versi mobile menjadi prioritas utama (primary).</p></details><hr><p><strong>19. Dalam Image Optimization, teknik apa yang harus diterapkan?</strong></p><ul><li>A. Menggunakan format gambar modern seperti WebP.</li><li>B. Selalu menggunakan format PNG untuk foto produk karena kualitasnya paling tinggi tanpa kompresi.</li><li>C. Menggunakan atribut <code>alt</code> yang deskriptif dan kaya keyword.</li><li>D. Menggunakan atribut <code>srcset</code> untuk menyajikan gambar responsif sesuai ukuran layar.</li><li>E. Menghapus atribut width dan height agar gambar fleksibel.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: A, C, D</strong></p><p><strong>Penjelasan:</strong> B salah (WebP/JPEG lebih baik untuk foto karena kompresi). E salah (menghapus dimensi menyebabkan CLS buruk).</p></details><hr><p><strong>20. Apa kesalahan umum (Common Mistakes) yang sering terjadi dalam implementasi SEO teknis?</strong></p><ul><li>A. Memblokir akses ke file CSS dan JavaScript melalui robots.txt.</li><li>B. Lupa menambahkan atribut <code>alt</code> pada tag <code>&lt;img&gt;</code>.</li><li>C. Menggunakan History API untuk navigasi.</li><li>D. Tidak memiliki tag kanonikal pada halaman yang memiliki duplikat.</li><li>E. Memiliki loading speed yang lambat karena gambar yang tidak dioptimasi.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: A, B, D, E</strong></p><p><strong>Penjelasan:</strong> C justru adalah best practice, bukan kesalahan. Kesalahan fatal adalah memblokir resource rendering (A), aksesibilitas buruk (B), isu duplikasi (D), dan performa buruk (E).</p></details>`,88)])])}const k=n(s,[["render",l]]);export{p as __pageData,k as default};
